// Groups conversation-log events under the call that produced them (skill
// engine only). A "Tool call: <name>" row becomes a collapsible header for the
// memory writes it caused. Membership is decided purely by id: the engine
// stamps each tool-produced memory write with the dispatching call's id
// (metadata.mantle_write_provenance.tool_call_id), and a tool row collects
// exactly the writes whose provenance id equals its own metadata.tool_call_id.
// The join is list-wide — writes are appended to the tracker before their
// tool-run marker, so a write can sit anywhere relative to its call; it is
// nested under the call row wherever it occurred and removed from the top
// level. A tool row without a tool_call_id (engine-invoked hooks / execute
// steps) gets no children — the correct representation, since there is nothing
// to attribute to it.
//
// LLM call rows group the discovered facts their side-channel calls produced
// (the __discovered__ scratchpad write that follows the fact-discovery call)
// and the writes of the `set_fields` tool the call predicted — set_fields is an
// internal tool, so its row is dropped and its writes fold into the predicting
// call's caret. Both are adjacency joins: the engine does not stamp those
// writes with the producing LLM call's id, so immediate succession in the
// stream is the only signal available. A future engine stamp makes it an id
// join.
import { ConversationEventType, type ConversationEvent, type UnionEventType } from "../../types";
import {
  isHiddenSystemMemoryEntry,
  isMemoryWriteEvent,
  isToolRunEvent,
  isUtterance,
} from "../../utils";

// Engine router `activate` is already narrated as "<Skill> skill activated".
// MCP servers can also expose a tool named `activate`; only hide the local
// router so those calls still appear in the log.
const ENGINE_ACTIVATE_TOOL = "activate";

// `set_fields` is the internal tool the orchestrator invokes to write the
// memory an LLM call predicted. It is not surfaced as its own log row; its
// writes fold into the caret of the LLM call that predicted it. As with
// `activate`, only the local framework tool is folded — an MCP server may
// expose a tool of the same name, and those stay visible.
const ENGINE_SET_FIELDS_TOOL = "set_fields";

const DISCOVERED_ENTRY_SUFFIX = "__discovered__";

export type ConversationLogItem =
  | { kind: "event"; event: UnionEventType }
  | { kind: "tool-group"; call: ConversationEvent; children: ConversationEvent[] }
  | { kind: "llm-group"; call: ConversationEvent; children: ConversationEvent[] };

function provenanceToolCallId(event: ConversationEvent): string | undefined {
  return event.metadata?.mantle_write_provenance?.tool_call_id ?? undefined;
}

function isDiscoveredFactsWrite(event: ConversationEvent): boolean {
  return (
    isMemoryWriteEvent(event) && (event.name?.split(".").pop() ?? "") === DISCOVERED_ENTRY_SUFFIX
  );
}

function isHiddenEngineActivate(event: ConversationEvent): boolean {
  return (
    event.metadata?.tool_name === ENGINE_ACTIVATE_TOOL && event.metadata?.tool_source === "local"
  );
}

function isHiddenSetFields(event: ConversationEvent): boolean {
  return (
    event.metadata?.tool_name === ENGINE_SET_FIELDS_TOOL && event.metadata?.tool_source === "local"
  );
}

// Shares the MemoryWriteEvent visibility predicate: system housekeeping writes
// render as null, so they must not count toward the children that warrant a
// caret (else the caret expands to nothing). The __discovered__ scratchpad is a
// system.* entry both sides surface.
function isVisibleMemoryWrite(event: ConversationEvent): boolean {
  return !isHiddenSystemMemoryEntry(event.name ?? "");
}

export function groupEventsByToolCall(events: UnionEventType[]): ConversationLogItem[] {
  // The set of tool-run call ids present as rows: a write only nests under a
  // call that is actually shown, so an orphan-id write stays at the top level.
  const presentCallIds = new Set<string>();
  for (const event of events) {
    if (isToolRunEvent(event) && event.metadata?.tool_call_id) {
      presentCallIds.add(event.metadata.tool_call_id);
    }
  }

  // Collect every tool-produced write by the id of the call that produced it,
  // list-wide: writes precede their marker on the tracker, so a call's writes
  // can appear before the call row is reached.
  const writesByCallId = new Map<string, ConversationEvent[]>();
  const claimedWrites = new Set<ConversationEvent>();
  for (const event of events) {
    if (isUtterance(event) || !isMemoryWriteEvent(event)) {
      continue;
    }
    const callId = provenanceToolCallId(event);
    if (callId === undefined || !presentCallIds.has(callId)) {
      continue;
    }
    const bucket = writesByCallId.get(callId);
    if (bucket) {
      bucket.push(event);
    } else {
      writesByCallId.set(callId, [event]);
    }
    claimedWrites.add(event);
  }

  const items: ConversationLogItem[] = [];
  // The only adjacency join left: a discovered-facts write immediately after
  // its fact-discovery LLM call row attaches to that row.
  let openLlmGroup: Extract<ConversationLogItem, { kind: "llm-group" }> | null = null;

  for (const event of events) {
    if (isUtterance(event)) {
      openLlmGroup = null;
      items.push({ kind: "event", event });
      continue;
    }
    if (isToolRunEvent(event)) {
      if (isHiddenEngineActivate(event)) {
        openLlmGroup = null;
        continue;
      }
      const callId = event.metadata?.tool_call_id ?? undefined;
      const children = (callId !== undefined ? (writesByCallId.get(callId) ?? []) : []).filter(
        isVisibleMemoryWrite,
      );
      // Fold set_fields into the LLM call that predicted it: its writes join
      // that row's caret and the set_fields row itself is dropped. The LLM row
      // is the one immediately preceding it in the stream, so it is the open
      // group here. Without an open group (a legacy tracker with no recorded
      // LLM call) it falls through to its own row so the writes stay visible.
      if (isHiddenSetFields(event) && openLlmGroup) {
        openLlmGroup.children.push(...children);
        continue;
      }
      openLlmGroup = null;
      items.push({ kind: "tool-group", call: event, children });
      continue;
    }
    if (event.conversationEventType === ConversationEventType.LlmCallRecorded) {
      openLlmGroup = { kind: "llm-group", call: event, children: [] };
      items.push(openLlmGroup);
      continue;
    }
    // Writes already nested under their producing tool call are removed from
    // the top level wherever they occurred.
    if (isMemoryWriteEvent(event) && claimedWrites.has(event)) {
      continue;
    }
    if (openLlmGroup && isDiscoveredFactsWrite(event)) {
      openLlmGroup.children.push(event);
      continue;
    }
    openLlmGroup = null;
    items.push({ kind: "event", event });
  }

  return items;
}
